var r=[{slug:"tyrolium-ui",name:"Tyrolium UI",icon:"ri-layout-masonry-line",gradient:"linear-gradient(135deg, #0533c8 0%, #bf0000 100%)",tagline:"Biblioth\xE8que de composants Angular partag\xE9e",taglineEn:"Shared Angular component library",description:"Librairie Angular interne partag\xE9e par tous les sites du groupe. Navbar universelle, Auth, CTA, Footer, th\xE8mes et langues.",descriptionEn:"Internal Angular library shared across all group sites. Universal navbar, Auth, CTA, Footer, themes and languages.",longDesc:"Tyrolium UI est la biblioth\xE8que de composants Angular d\xE9velopp\xE9e en interne et partag\xE9e entre tous les projets du groupe Tyrolium. Elle fournit la navbar universelle avec gestion des th\xE8mes (clair/sombre/auto), des langues (FR/EN) et du menu d'applications Tyrolium, le composant CTA, le footer, la modal d'authentification Useritium, plusieurs directives utilitaires (gloss effect) et les services de th\xE8me et langue. Construite avec Angular standalone components, elle garantit une coh\xE9rence visuelle parfaite sur l'ensemble de l'\xE9cosyst\xE8me.",longDescEn:"Tyrolium UI is an internally developed Angular component library shared across all Tyrolium group projects. It provides the universal navbar with theme (light/dark/auto), language (FR/EN) and Tyrolium apps menu management, the CTA component, footer, Useritium authentication modal, several utility directives (gloss effect) and theme/language services. Built with Angular standalone components, it ensures perfect visual consistency across the entire ecosystem.",status:"active",tech:["Angular","TypeScript","CSS"],github:"https://github.com/TheMaxium69/Tyrolium-UI",link:"https://design.tyrolium.fr",usedBy:[{name:"tyrolium.fr",url:"https://tyrolium.fr"},{name:"solidserv.fr",url:"https://solidserv.fr"},{name:"tyroserv.fr",url:"https://tyroserv.fr"},{name:"tyrociel.fr",url:"https://tyrociel.fr"},{name:"gamenium.fr",url:"https://gamenium.fr"},{name:"useritium.fr",url:"https://useritium.fr"},{name:"nexiumiacrm.fr",url:"https://nexiumiacrm.fr"},{name:"influnias.fr",url:"https://influnias.fr"},{name:"vturias.fr",url:"https://vturias.fr"}],version:"V1.0",contributors:["Maxime Tournier"],features:["Navbar universelle (th\xE8me, langues, apps)","Composants standalone Angular","CTA, Footer, Auth Modal","Service de th\xE8me dark/light/auto","Service de langue FR/EN","Directive Gloss Effect"],featuresEn:["Universal navbar (theme, languages, apps)","Angular standalone components","CTA, Footer, Auth Modal","Dark/light/auto theme service","FR/EN language service","Gloss Effect directive"]},{slug:"tyrositeframework",name:"TyroSiteFramework",icon:"ri-code-s-slash-line",gradient:"linear-gradient(135deg, #0533c8 0%, #bf0000 100%)",tagline:"Framework PHP pour sites clients ultra-rapides",taglineEn:"PHP framework for lightning-fast client websites",description:"Framework PHP interne con\xE7u pour d\xE9velopper des sites et applications web clients tr\xE8s rapidement, avec un syst\xE8me de composants r\xE9utilisables et des imports automatis\xE9s.",descriptionEn:"Internal PHP framework designed to build client websites and web applications very quickly, with reusable components and automated imports.",longDesc:"TyroSiteFramework est le framework PHP interne de Tyrolium, pens\xE9 avant tout pour produire des sites et applications web clients de fa\xE7on rapide et structur\xE9e. Son principe central repose sur un syst\xE8me de composants .phtml r\xE9utilisables avec imports automatis\xE9s, ce qui permet de construire une page enti\xE8re en assemblant des briques sans configuration fastidieuse. Le routing par identifiants de page simplifie la navigation, tandis que le syst\xE8me d'extensions modulaire permet d'ajouter des fonctionnalit\xE9s au cas par cas. Il peut \xE9galement exposer des endpoints API, mais c'est le d\xE9veloppement de sites web pour les clients de Tyrolium qui reste son usage principal. Z\xE9ro d\xE9pendance externe, contr\xF4le total du code.",longDescEn:"TyroSiteFramework is Tyrolium's internal PHP framework, designed primarily to build client websites and web applications quickly and in a structured way. Its core principle is a reusable .phtml component system with automated imports, making it possible to build a full page by assembling blocks without tedious configuration. Page ID-based routing simplifies navigation, while the modular extension system allows features to be added on a per-project basis. It can also expose API endpoints, but building websites for Tyrolium's clients remains its primary use case. Zero external dependencies, full code control.",status:"active",tech:["PHP","MySQL","No-dependency"],github:"https://github.com/TheMaxium69/TyroSiteFrameWork",usedBy:[{name:"dashboard.useritium.fr",url:"https://dashboard.useritium.fr"},{name:"batirpositif.fr",url:"https://batirpositif.fr"},{name:"cls-habitat.fr",url:"https://www.cls-habitat.fr/"},{name:"maximetournier.fr",url:"https://maximetournier.fr"},{name:"avra-formules.fr",url:"https://story.avra.tyrolium.fr/"}],version:"V2.0",contributors:["Maxime Tournier"],features:["Composants .phtml r\xE9utilisables avec imports automatis\xE9s","D\xE9veloppement de sites clients ultra-rapide","Routing bas\xE9 sur des IDs de page","Syst\xE8me d'extensions modulaire","Z\xE9ro d\xE9pendance externe","Support API REST en option"],featuresEn:["Reusable .phtml components with automated imports","Ultra-fast client website development","Page ID-based routing","Modular extension system","Zero external dependencies","Optional REST API support"]},{slug:"api-getserver-minecraft",name:"ApiGetServer for Minecraft",icon:"ri-server-line",gradient:"linear-gradient(135deg, #0533c8 0%, #bf0000 100%)",tagline:"API PHP pour exposer les donn\xE9es d'un serveur Minecraft",taglineEn:"PHP API to expose Minecraft server data externally",description:"API PHP h\xE9berg\xE9e sur le m\xEAme serveur que Minecraft, permettant d'exposer \xE0 l'ext\xE9rieur les donn\xE9es cl\xE9s : joueurs connect\xE9s, stats, map, et int\xE9gration des plugins majeurs.",descriptionEn:"PHP API hosted on the same server as Minecraft, exposing key data externally: connected players, stats, map info and integration with major plugins.",longDesc:"ApiGetServer for Minecraft est une API PHP con\xE7ue pour communiquer avec un serveur Minecraft h\xE9berg\xE9 sur la m\xEAme machine. Elle permet d'exposer \xE0 l'ext\xE9rieur des informations importantes comme le nombre de joueurs connect\xE9s, les statistiques par joueur ou les donn\xE9es de la map. Elle s'int\xE8gre \xE9galement avec les plugins Minecraft les plus courants - EssentialsX, LuckPerms, le plugin Factions et TyroPlugin - en lisant directement leurs fichiers .json et .db. Compatible avec les plateformes Bukkit, Spigot et Paper, elle sert de pont entre l'infrastructure Minecraft et les applications web externes.",longDescEn:"ApiGetServer for Minecraft is a PHP API designed to communicate with a Minecraft server hosted on the same machine. It exposes key information externally, such as the number of connected players, per-player statistics and map data. It also integrates with the most common Minecraft plugins - EssentialsX, LuckPerms, the Factions plugin and TyroPlugin - by directly reading their .json and .db files. Compatible with Bukkit, Spigot and Paper, it acts as a bridge between the Minecraft infrastructure and external web applications.",status:"active",tech:["PHP","JSON","SQLite"],github:"https://github.com/TheMaxium69/Api-GetServerMinecraft",usedBy:[{name:"TyroServ",url:"https://tyroserv.fr"},{name:"TyroPlugin",url:"https://github.com/TheMaxium69/TyroPlugin"},{name:"Launcher de TyroServ",url:"https://github.com/TheMaxium69/Launcher-TyroServS3"}],version:"V1.0",contributors:["Maxime Tournier"],features:["Nombre de joueurs connect\xE9s en temps r\xE9el","Statistiques par joueur","Informations sur la map","Int\xE9gration EssentialsX, LuckPerms, Factions","Int\xE9gration TyroPlugin","Compatible Bukkit / Spigot / Paper"],featuresEn:["Real-time connected player count","Per-player statistics","Map information","EssentialsX, LuckPerms, Factions integration","TyroPlugin integration","Compatible with Bukkit / Spigot / Paper"]},{slug:"genjson-minecraft",name:"GenJSON for Minecraft",icon:"ri-braces-line",gradient:"linear-gradient(135deg, #0533c8 0%, #bf0000 100%)",tagline:"G\xE9n\xE9rateur automatique de fichiers JSON pour mods Minecraft",taglineEn:"Automatic JSON file generator for Minecraft mods",description:"Script PowerShell qui g\xE9n\xE8re automatiquement les fichiers JSON de ressources Minecraft - blockstates, mod\xE8les d'items et de blocs - pour acc\xE9l\xE9rer le d\xE9veloppement de mods.",descriptionEn:"PowerShell script that automatically generates Minecraft resource JSON files - blockstates, item and block models - to speed up mod development.",longDesc:"GenJSON for Minecraft est un script PowerShell con\xE7u pour automatiser la g\xE9n\xE9ration des fichiers JSON de ressources n\xE9cessaires au d\xE9veloppement de mods Minecraft. Cr\xE9er manuellement les fichiers blockstates, les mod\xE8les d'items et de blocs pour chaque \xE9l\xE9ment d'un mod est une t\xE2che r\xE9p\xE9titive et fastidieuse. GenJSON prend en charge cette g\xE9n\xE9ration automatiquement \xE0 partir d'une configuration simple, pour produire en masse l'ensemble des fichiers JSON conformes aux sp\xE9cifications de Minecraft. Utilis\xE9 en production pour TyroServ et TyroMod.",longDescEn:"GenJSON for Minecraft is a PowerShell script designed to automate the generation of resource JSON files required for Minecraft mod development. Manually creating blockstate files, item models and block models for every element in a mod is a repetitive and time-consuming task. GenJSON handles this generation automatically from a simple configuration, mass-producing all JSON files in line with Minecraft's specifications. Used in production for TyroServ and TyroMod.",status:"beta",tech:["PowerShell"],github:"https://github.com/TheMaxium69/generatedJsonMinecraftMod",usedBy:[{name:"TyroServ",url:"https://tyroserv.fr"},{name:"TyroMod",url:"https://github.com/TheMaxium69/TyroMod"}],version:"V0.2-beta",contributors:["Maxime Tournier"],features:["G\xE9n\xE9ration automatique des fichiers blockstates","G\xE9n\xE9ration des mod\xE8les d'items (.json)","G\xE9n\xE9ration des mod\xE8les de blocs (.json)","G\xE9n\xE9ration en masse depuis une configuration simple","Aucune d\xE9pendance externe (PowerShell natif)","Compatible Minecraft Forge uniquement"],featuresEn:["Automatic blockstate file generation","Item model generation (.json)","Block model generation (.json)","Bulk generation from a simple configuration","No external dependencies (native PowerShell)","Minecraft Forge only"]},{slug:"tyrogit",name:"TyroGit Client",icon:"ri-git-repository-line",gradient:"linear-gradient(135deg, #0533c8 0%, #bf0000 100%)",tagline:"Client Git visuel avec int\xE9gration de th\xE8mes",taglineEn:"Visual Git client with theme integration",description:"Alternative \xE0 GitHub Desktop d\xE9velopp\xE9e en interne, avec support multi-remote, logos de d\xE9p\xF4t personnalis\xE9s via .tyrogit et int\xE9gration des th\xE8mes Tyrolium.",descriptionEn:"An internally developed alternative to GitHub Desktop, with multi-remote support, custom repository logos via .tyrogit and Tyrolium theme integration.",longDesc:"TyroGit Client est le client Git de bureau de Tyrolium, con\xE7u comme une alternative \xE0 GitHub Desktop. Il se connecte aux principaux h\xE9bergeurs Git - GitHub, GitLab et repo.tyrolium.fr - avec un support multi-remote natif sur un m\xEAme d\xE9p\xF4t. Sa particularit\xE9 : la prise en charge des fichiers .tyrogit, qui permettent d'associer un logo et une identit\xE9 visuelle \xE0 chaque d\xE9p\xF4t directement dans l'interface. Construit avec Electron.js, il embarque une int\xE9gration compl\xE8te des th\xE8mes clair et sombre pour une exp\xE9rience coh\xE9rente avec l'\xE9cosyst\xE8me Tyrolium.",longDescEn:"TyroGit Client is Tyrolium's desktop Git client, designed as an alternative to GitHub Desktop. It connects to the main Git providers - GitHub, GitLab and repo.tyrolium.fr - with native multi-remote support on a single repository. Its standout feature: .tyrogit file support, which lets you associate a logo and visual identity with each repository directly in the interface. Built with Electron.js, it includes full light and dark theme integration for an experience consistent with the Tyrolium ecosystem.",status:"beta",tech:["Electron.js","Node.js","Git"],github:"https://github.com/TheMaxium69/TyroGit",version:"V0.1-beta",contributors:["Maxime Tournier"],features:["Interface visuelle type GitHub Desktop","Logos de d\xE9p\xF4t personnalis\xE9s via .tyrogit","Support multi-remote natif","Compatible GitHub, GitLab, repo.tyrolium.fr","Int\xE9gration th\xE8mes clair/sombre","Gestion des d\xE9p\xF4ts locaux et distants"],featuresEn:["GitHub Desktop-style visual interface","Custom repository logos via .tyrogit","Native multi-remote support","Compatible with GitHub, GitLab, repo.tyrolium.fr","Light/dark theme integration","Local and remote repository management"]},{slug:"discordbot-framework",name:"DiscordBot Framework",icon:"ri-discord-line",gradient:"linear-gradient(135deg, #0533c8 0%, #bf0000 100%)",tagline:"Framework Java pour cr\xE9er des bots Discord rapidement",taglineEn:"Java framework for building Discord bots fast",description:"Framework interne bas\xE9 sur JDA Discord qui permet \xE0 Tyrolium de d\xE9velopper des bots Discord rapidement pour ses filiales et ses clients.",descriptionEn:"Internal framework built on JDA Discord that lets Tyrolium develop Discord bots quickly for its subsidiaries and clients.",longDesc:"DiscordBot Framework est la base commune utilis\xE9e chez Tyrolium pour cr\xE9er des bots Discord en Java via JDA (Java Discord API). Il abstrait la configuration initiale, la gestion des commandes et les \xE9v\xE9nements Discord pour permettre de d\xE9marrer un nouveau bot en quelques minutes. Con\xE7u pour \xEAtre r\xE9utilis\xE9 sur l'ensemble de l'\xE9cosyst\xE8me Tyrolium - filiales et projets clients - il est actuellement \xE0 la base de TyroBot, TyroServBot et SolidServBot.",longDescEn:"DiscordBot Framework is the shared foundation used at Tyrolium to build Discord bots in Java via JDA (Java Discord API). It abstracts initial setup, command handling and Discord events to allow a new bot to be started in minutes. Designed for reuse across the entire Tyrolium ecosystem - subsidiaries and client projects - it currently powers TyroBot, TyroServBot and SolidServBot.",status:"active",tech:["Java","JDA","Discord"],github:"https://github.com/TheMaxium69/DiscordBotFrameWork",usedBy:[{name:"TyroBot",url:"https://github.com/TheMaxium69/TyroBotDiscord"},{name:"TyroServBot",url:"https://github.com/TheMaxium69/TyroServBotDiscord"},{name:"SolidServBot",url:"https://github.com/TheMaxium69/SolidServ-Bot"}],version:"V1.0",contributors:["Maxime Tournier"],features:["Base commune pour bots Discord en Java","Int\xE9gration JDA (Java Discord API)","Gestion des commandes slash et pr\xE9fix\xE9es","Gestion des \xE9v\xE9nements Discord","D\xE9marrage d'un nouveau bot en quelques minutes","R\xE9utilisable sur l'ensemble de l'\xE9cosyst\xE8me Tyrolium"],featuresEn:["Shared foundation for Java Discord bots","JDA (Java Discord API) integration","Slash and prefix command handling","Discord event management","New bot up and running in minutes","Reusable across the entire Tyrolium ecosystem"]},{slug:"chatbox-twitch-framework",name:"ChatBoxTwitch Framework",icon:"ri-live-line",gradient:"linear-gradient(135deg, #0533c8 0%, #bf0000 100%)",tagline:"Framework PHP pour styliser les chatbox Streamlabs",taglineEn:"PHP framework to style and host Streamlabs chat boxes",description:"Framework PHP h\xE9berg\xE9 sur Apache/Nginx qui cr\xE9e un environnement de personnalisation des chatbox Streamlabs en HTML/CSS/JS - con\xE7u pour les talents d'Influnias et Vturias.",descriptionEn:"PHP framework hosted on Apache/Nginx that creates a customisation environment for Streamlabs chat boxes in HTML/CSS/JS - designed for Influnias and Vturias talents.",longDesc:"ChatBoxTwitch Framework est un framework PHP qui cr\xE9e un environnement d'h\xE9bergement et de stylisation pour les chatbox Streamlabs. Une fois d\xE9ploy\xE9 sur un serveur Apache ou Nginx, il permet de personnaliser enti\xE8rement l'apparence du chat Twitch - messages, couleurs, animations, polices - via HTML, CSS et JavaScript. L'URL g\xE9n\xE9r\xE9e est ensuite int\xE9gr\xE9e directement comme source navigateur dans OBS ou Streamlabs. Con\xE7u pour d\xE9ployer rapidement des th\xE8mes de chatbox sur mesure pour les streamers talents d'Influnias et de Vturias.",longDescEn:"ChatBoxTwitch Framework is a PHP framework that creates a hosting and styling environment for Streamlabs chat boxes. Once deployed on an Apache or Nginx server, it allows full customisation of the Twitch chat appearance - messages, colours, animations, fonts - via HTML, CSS and JavaScript. The generated URL is then integrated directly as a browser source in OBS or Streamlabs. Designed to quickly deploy custom chat box themes for streamer talents at Influnias and Vturias.",status:"active",tech:["PHP","HTML","CSS","JavaScript"],github:"https://github.com/TheMaxium69/ChatBoxTheme-Template",usedBy:[{name:"AuroreTVv",url:"https://github.com/TheMaxium69/ChatBoxTheme-AuroreTVv"},{name:"DoubleT",url:"https://github.com/TheMaxium69/ChatBoxTheme-DoubleT"}],version:"V1.0",contributors:["Maxime Tournier"],features:["Environnement d'h\xE9bergement chatbox sur Apache/Nginx","Personnalisation HTML/CSS/JS compl\xE8te","Compatible Streamlabs (source navigateur OBS)","Th\xE8mes de chat sur mesure par streamer","D\xE9ploiement rapide de nouveaux th\xE8mes","Con\xE7u pour les talents Influnias & Vturias"],featuresEn:["Chat box hosting environment on Apache/Nginx","Full HTML/CSS/JS customisation","Streamlabs compatible (OBS browser source)","Per-streamer custom chat themes","Fast deployment of new themes","Designed for Influnias & Vturias talents"]},{slug:"tyrolium-ip",name:"Tyrolium IP",icon:"ri-map-pin-user-line",gradient:"linear-gradient(135deg, #0533c8 0%, #bf0000 100%)",tagline:"Affiche votre adresse IP publique en un clic",taglineEn:"Displays your public IP address instantly",description:"Petit outil web qui affiche l'adresse IP publique du visiteur telle que vue par l'infrastructure Tyrolium / SolidServ, sans inscription ni tracking.",descriptionEn:"Small web tool that displays the visitor's public IP address as seen by the Tyrolium / SolidServ infrastructure, with no sign-up or tracking.",longDesc:"Tyrolium IP est un outil simple h\xE9berg\xE9 sur ip.tyrolium.fr qui affiche l'adresse IP publique du visiteur en temps r\xE9el. Construit en Angular sur le design system Tyrolium UI, il g\xE8re proprement les erreurs r\xE9seau ou backend (message d'erreur d\xE9di\xE9 plut\xF4t qu'une page cass\xE9e), et propose le support FR/EN ainsi que les th\xE8mes clair/sombre au m\xEAme titre que le reste de l'\xE9cosyst\xE8me.",longDescEn:"Tyrolium IP is a simple tool hosted on ip.tyrolium.fr that displays the visitor's public IP address in real time. Built in Angular on the Tyrolium UI design system, it gracefully handles network or backend errors (a dedicated error message instead of a broken page) and offers FR/EN support as well as light/dark themes, consistent with the rest of the ecosystem.",status:"active",tech:["Angular","PHP","TypeScript"],github:"https://github.com/TheMaxium69/Tyrolium-Ip",link:"https://ip.tyrolium.fr",version:"V3.0",contributors:["Maxime Tournier"],features:["D\xE9tection instantan\xE9e de l'IP publique","Gestion propre des erreurs r\xE9seau/backend","Th\xE8me clair/sombre","Support FR/EN","Construit sur Tyrolium UI"],featuresEn:["Instant public IP detection","Clean network/backend error handling","Light/dark theme","FR/EN support","Built on Tyrolium UI"]},{slug:"tyrolium-speedtest",name:"Tyrolium SpeedTest",icon:"ri-speed-up-line",gradient:"linear-gradient(135deg, #0533c8 0%, #bf0000 100%)",tagline:"Test de d\xE9bit bas\xE9 sur le moteur open-source LibreSpeed",taglineEn:"Speed test powered by the open-source LibreSpeed engine",description:"Test de vitesse de connexion (d\xE9bit, ping, gigue) h\xE9berg\xE9 sur speedtest.tyrolium.fr, avec une interface Angular aux couleurs Tyrolium.",descriptionEn:"Connection speed test (throughput, ping, jitter) hosted on speedtest.tyrolium.fr, with a Tyrolium-branded Angular interface.",longDesc:"Tyrolium SpeedTest mesure le d\xE9bit descendant, le d\xE9bit montant, le ping et la gigue de votre connexion. Le moteur de mesure repose sur LibreSpeed (github.com/librespeed/speedtest), un projet open-source sous licence LGPL cr\xE9\xE9 par Federico Dossena et int\xE9gr\xE9 tel quel c\xF4t\xE9 backend/worker - aucune r\xE9\xE9criture de la logique de mesure. L'interface, elle, a \xE9t\xE9 enti\xE8rement reconstruite en Angular sur le design system Tyrolium UI, avec des jauges fa\xE7on compteur de vitesse : bleu pour le t\xE9l\xE9chargement, rouge pour l'envoi.",longDescEn:"Tyrolium SpeedTest measures your connection's download speed, upload speed, ping and jitter. The measurement engine is built on LibreSpeed (github.com/librespeed/speedtest), an open-source project under the LGPL license created by Federico Dossena, integrated as-is on the backend/worker side - no rewrite of the measurement logic. The interface itself was fully rebuilt in Angular on the Tyrolium UI design system, with car-speedometer-style gauges: blue for download, red for upload.",status:"active",tech:["Angular","PHP","LibreSpeed"],github:"https://github.com/TheMaxium69/Tyrolium-SpeedTest",link:"https://speedtest.tyrolium.fr",version:"V2.0",contributors:["Maxime Tournier"],features:["Mesure d\xE9bit descendant / montant","Mesure du ping et de la gigue","Jauges fa\xE7on compteur de vitesse (bleu/rouge)","Moteur LibreSpeed (open-source, LGPL)","Th\xE8me clair/sombre, support FR/EN"],featuresEn:["Download / upload speed measurement","Ping and jitter measurement","Car-speedometer-style gauges (blue/red)","LibreSpeed engine (open-source, LGPL)","Light/dark theme, FR/EN support"]}];function i(e){return r.find(t=>t.slug===e)}export{r as a,i as b};
